const r=t=>String(t||"").replace(/\D/g,"");function e(t){const n=r(t);return/^0\d{8,10}$/.test(n)?null:"연락처를 숫자로 입력해 주세요 (예: 010-1234-5678)"}function i(t){const n=r(t);return/^01[016789]\d{7,8}$/.test(n)?null:"휴대폰 번호 10-11자리를 입력해 주세요 (예: 01012345678)"}function l(t){const n=r(t);return/^\d{10}$/.test(n)?null:"사업자등록번호 숫자 10자리를 입력해 주세요"}export{l as a,i as b,e as v};
